p.extended-example:
typedef union Information_Fields
{
    struct
    {
        char *load_address;
        char *execute_address;
    } load_exec;
    struct
    {
        int part_1;
        int part_2;
    } date_type;
} Information_Fields;

_kernel_oserror *fsentry_getbytes(FSEntry_GetBytes_Parameter *parm)
{
    OpenFile *file = openfile_from_handle(parm->getbytes_definition.handle);

    if (file->position >= file->length)
    {
        /* End of file: tell the veneer no byte was read, so that it
           reports this to FileSwitch through the C flag. */
        parm->getbytes_result.got_the_byte = No;
        return NULL;
    }

    parm->getbytes_result.byte_got = file->data[file->position++];
    parm->getbytes_result.got_the_byte = Yes;
    return NULL;
}
